def Maintenance_Config_Reset(driver):

    mod.Switch_Default(driver)
    mod.Page_Switch(driver,"Maintenance")
    mod.SubPage_Switch(driver,"Config Reset")
    mod.Switch_Frame(driver)
    driver.find_element(By.NAME, "rpConfigReset").click()
    # alert_accept(driver) # "enter"
    WebDriverWait(driver, 10).until(EC.alert_is_present()).accept()
    # time.sleep(60)

    #--------no need to wait for long time?-------------#*add
    time.sleep(1)
    state_n = ""
    while(state_n !="idle"):
        time.sleep(2)    
        state_n = driver.find_element(By.CLASS_NAME, "state").text

def Add_Screenshot_Text_InWordFile(text,doc,file_name):
    doc.add_paragraph(text)
    screenshot_path = f'{str(datetime.datetime.now()).split(":")[0]}{str(datetime.datetime.now()).split(":")[1]}.{str(datetime.datetime.now()).split(":")[2][:5]}_screenshot.png'
    pyautogui.screenshot(screenshot_path)               
    doc.add_picture( screenshot_path, width=Inches(6.0))    
    doc.save(f"{file_name.split('.txt')[0]}.docx")

def FW_Logout(driver):    
    
    # Statistics > Online Users > kick out       > quit
    try:
        mod.Switch_Default(driver)
        mod.Page_Switch(driver,"Statistics")
        mod.SubPage_Switch(driver,"Online Users")
        mod.Switch_Frame(driver)
        time.sleep(2)
        # find session include '*' one, kick
        for index in range(driver.find_elements(By.CLASS_NAME,"rponlineusr_user_session").__len__()):
            if("*" in driver.find_elements(By.CLASS_NAME,"rponlineusr_user_session")[index].text):            
                session1 = driver.find_elements(By.CLASS_NAME,"rponlineusr_user_session")[index].text
                print(f"             [Statistics - Online Users] session:{session1}")
                driver.find_elements(By.NAME,'rponlineusr_btnKick')[index].click()   
                WebDriverWait(driver, 10).until(EC.alert_is_present()).accept()      
                break
        driver.find_element("LINK TEXT","Logout").click()  
    except:
        pass

def PrintException(file_name): # author:Apogentus, https://stackoverflow.com/questions/14519177/python-exception-handling-line-number
    exc_type, exc_obj, tb = real_sys.exc_info()
    f = tb.tb_frame
    lineno = tb.tb_lineno
    filename = f.f_code.co_filename
    linecache.checkcache(filename)
    # line = linecache.getline(f'             {filename}', lineno, f'             {f.f_globals}')
    line = linecache.getline(filename, lineno, f.f_globals)
    # print(f'EXCEPTION IN ({filename}, LINE {lineno} "{line.strip()}"):{exc_obj}')
    # print_(f'EXCEPTION IN ( LINE {lineno} "{line.strip()}"):{get_first_line(exc_obj)}',file = open(file_name, '+a'))

    print(f'             traceback start',file = open(file_name, '+a'))
    with io.StringIO() as buffer:
        traceback.print_exc(file=buffer)
        err_info = buffer.getvalue()

    # tb = traceback.extract_tb(err_info.__traceback__)
    # filename, line, _, _ = tb[-1]

    print(err_info,file = open(file_name, '+a'))
    print(f'             traceback end',file = open(file_name, '+a'))


