def EMS_Set_Prepare(driver,snmp_get,snmp_set,snmp_version,username,password):

    # Sys - Access Control - SNMP, input value from ENV.txt ---
    # path: Sys > Access Control > SNMP
    mod.Switch_Default(driver)
    mod.Page_Switch(driver,"Sys")
    # mod.Switch_Frame(driver)
    mod.Tab_Switch(driver,"Access Control")
    mod.Switch_Frame(driver)
    mod.Tab_Switch(driver,"SNMP")
    
    # input get community
    driver.find_element(By.NAME, "rpsysacc_snmp_ipt_get_com").clear()
    driver.find_element(By.NAME, "rpsysacc_snmp_ipt_get_com").send_keys(snmp_get)
    # input set community    
    driver.find_element(By.NAME, "rpsysacc_snmp_ipt_set_com").clear()
    driver.find_element(By.NAME, "rpsysacc_snmp_ipt_set_com").send_keys(snmp_set)
    # select version
    # print(f"snmp_version:{snmp_version}")
    # Select(driver.find_element(By.NAME, "rpsysacc_snmp_slt_version")).select_by_visible_text(snmp_version)
    driver.find_element(By.XPATH, "/html/body/form/div[2]/div[1]/div[12]/select/option[1]").click()
    # rpsysacc_snmp_slt_version

    # click apply
    driver.find_element(By.NAME, "rpsysacc_snmp_button_apply").click()    

    # Sys - Users Account, input value from ENV.txt ---
    # path: Sys > Users Account
    mod.Switch_Default(driver)
    mod.Tab_Switch(driver,"Users Account")
    mod.Switch_Frame(driver)
    # input name
    driver.find_element(By.NAME, "rpsysuser_input_name").clear()
    driver.find_element(By.NAME, "rpsysuser_input_name").send_keys(username)
    # input password
    driver.find_element(By.NAME, "rpsysuser_input_password").clear()
    driver.find_element(By.NAME, "rpsysuser_input_password").send_keys(password)
    # input retype password to confirm
    driver.find_element(By.NAME, "rpsysuser_input_retypepassword").clear()
    driver.find_element(By.NAME, "rpsysuser_input_retypepassword").send_keys(password)
    # click apply
    driver.find_element(By.NAME, "rpsysuser_config_button_apply").click()    

def EMS_Case(driver,GLC1440_port,GLC1540_port,OLC3416B_port,OLC3416_42_port,file_name):

    MSC_card = ""
    MSC_slot = ""
    cardtype_case = 0
    list1 = []            # case, slot, port (str each element)

    # Home, get active card type --- 
    mod.Switch_Default(driver)
    mod.Page_Switch(driver,"Home")
    mod.Switch_Frame(driver)
    time.sleep(1)
    dict1={}
    for index in range(driver.find_elements(By.CLASS_NAME, "SysinfoList").__len__()):    
        if(driver.find_elements(By.CLASS_NAME, "td-table-content.SysinfoState")[index].text == "active"):            
            slot_n = driver.find_elements(By.CLASS_NAME, "td-table-content.i1")[index].text
            cardtype_n = driver.find_elements(By.CLASS_NAME, "td-table-content.SysinfoCardType.left-wrapper")[index].text
            # dict1[slot_n]=cardtype_n        
            dict1[cardtype_n] = slot_n     
    print("dict1:",end="")
    print(dict1)
    print(dict1.keys())
    for i in dict1.keys():
        # print("....")
        # print("i:"+i)
        # =
        if(("GLC1440X" in i) or ("GLC1540X" in i)):
            cardtype_case = 1
            # print("in case (1) GLC1440X, GLC1540X")        
            # print('{:>20}'.format(f"{i} slot:{dict1[i]},"))
            print(f"{i} slot:{dict1[i]}, in case (1) GLC1440X, GLC1540X",file = open(file_name, '+a'))        
            temp = "1," + dict1[i]
            if("GLC1440X" in i):
                temp = temp + "," + GLC1440_port
            else:
                temp = temp + "," + GLC1540_port

        elif(("OLC3416B" in i) or ("OLC3708" in i) or ("OLC3816" in i)):
            cardtype_case = 2
            # print("in case (2) OLC3416B, OLC3708, OLC3816")         
            print(f"{i} slot:{dict1[i]}, in case (2) OLC3416B, OLC3708, OLC3816",file = open(file_name, '+a'))                  
            temp = "2," + dict1[i]
            if("OLC3416B" in i):
                temp = temp + "," + OLC3416B_port
            else:
                temp = temp + "," + "0"      # other port ????????????????

        elif("OLC3416" in i):
            cardtype_case = 3
            # print("in case (3) OLC3416")              
            print(f"{i} slot:{dict1[i]}, in case (3) OLC3416",file = open(file_name, '+a'))        
            temp = "3," + dict1[i] + "," + OLC3416_42_port
            
        else:        
            cardtype_case = 4
            # print("not in any case")        
            print(f"{i} slot:{dict1[i]}, not in any case",file = open(file_name, '+a'))        
            temp = "4," + dict1[i] + "," + "0"
            if("MSC" in i):
                MSC_card = i
                MSC_slot = dict1[i]
        
        temp = temp + "," + i

        list1.append(temp)
            
    # print(f"list1:{list1}")

    print("======================================================================================",file = open(file_name, '+a'))
    

