    Delete_Profile_Test(driver,"__dial_plan_SFU",'ONT VoIP Dial Plan Profile',file_name)
    print(f"             [Profile] (Delete some profiles finished)",file = open(file_name, '+a'))
    print("======================================================================================",file = open(file_name, '+a'))

