    time.sleep(5)    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "Multicast").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "Multicast MAC").click()
    time.sleep(3)

    # check if clear, if not, delete   need_modify

    # select Slot Port  # need_modify
    e_mul.Multicast_MAC_Select_Slot(driver,slot)
    e_mul.Multicast_MAC_Select_Port(driver,port)
    
    # screenshot_path = f'{str(datetime.datetime.now()).split(":")[0]}{str(datetime.datetime.now()).split(":")[1]}.{str(datetime.datetime.now()).split(":")[2][:5]}_screenshot.png'
    # pyautogui.screenshot(screenshot_path)   

    # try:
    #     e_mul.Multicast_MAC_Select_Slot(driver,slot)
    # except:
    #     if_EMS_error = True
    #     print(f"             [Multicast - Multicast MAC] EMS Slot select fail",file = open(file_name, '+a')) 
    # try:
    #     e_mul.Multicast_MAC_Select_Port(driver,port)
    # except:
    #     if_EMS_error = True
    #     print(f"             [Multicast - Multicast MAC] EMS Port select fail",file = open(file_name, '+a')) 

    if(if_EMS_error == False):

        # e_mul.Multicast_MAC_Load(driver)

        # Multicast MAC Apply
        index = 0
        if_full = False
        # while(if_full == False):
        while(if_full == False and index < 10):
            index = index+1
            e_mul.Multicast_MAC_Address(driver,f"01:80:5e:00:00:0{index}")
            e_mul.Multicast_MAC_NNI_VLAN(driver,"4094")
            e_mul.Multicast_MAC_Add(driver)
            msg = alert_accept_text(driver)
            if(if_msg_not_success(msg)):
                print(f"             [Multicast - Multicast MAC] EMS msg:{msg} (counter:{index})",file = open(file_name, '+a'))
                break
            # try:
            #     driver.find_element(By.NAME, "rperror_btnBack").click()
            #     print(f"             [Multicast - Static Multicast - Multicast MAC] Max Capacity(8) = {index-1}",file = open(file_name, '+a'))
            #     if_full = True
            # except:
            #     pass

        # capacity check need_modify
        capacity_num_temp = driver.find_elements(By.CLASS_NAME, "zy_tr.multicast_mcastmac_table_row").__len__()
        print(f"             [Multicast - Multicast MAC] EMS capacity or input:{capacity_num_temp} ?",file = open(file_name, '+a')) 
        if(capacity_num_temp != 8):
            print(f"             [Multicast - Multicast MAC] EMS capacity != 8 fail",file = open(file_name, '+a')) 
            if_EMS_error = True

        if_mac_error = False
        if_nini_valn_error = False

        # Multicast MAC Check
        index_len = driver.find_elements(By.CLASS_NAME, "zy_tr.multicast_mcastmac_table_row").__len__()
        for index in range(index_len):
            if(driver.find_elements(By.CLASS_NAME, "zy_td.multicast_mcastmac_mac")[index].get_attribute("textContent") != f"01:80:5e:00:00:0{index+1}"):
                if_mac_error = True
            if(driver.find_elements(By.CLASS_NAME, "zy_td.multicast_mcastmac_nnivlan")[index].get_attribute("textContent") != "4094"):
                if_nini_valn_error = True
        if(if_mac_error == True):
            print(f"             [Multicast - Multicast MAC] EMS MAC Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [Multicast - Multicast MAC] EMS MAC Test Pass",file = open(file_name, '+a'))
        if(if_nini_valn_error == True):
            print(f"             [Multicast - Multicast MAC] EMS NINI-VLAN:4094 Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [Multicast - Multicast MAC] EMS NINI-VLAN:4094 Test Pass",file = open(file_name, '+a'))

        # --------------------- EMS web end -----------------------
        # --------------------- FW web start ----------------------
        # Multicast > Static Multicast > Multicast MAC
