        mod.Page_Switch(driver,"Multicast")
        mod.SubPage_Switch(driver,"Static Multicast")
        mod.Switch_Frame(driver)
        mod.SubPage_Switch(driver,"Multicast MAC")  
        time.sleep(3)
        mul.Slot_Select(driver,slot)
        mul.Port_Select(driver,port)
        time.sleep(3)
        mul.Load(driver)
        time.sleep(3)

        if_mac_error_fw = False
        if_nini_valn_error_fw = False

        # Multicast MAC Check
        index_len = driver.find_elements(By.CLASS_NAME, "td-table-content.rpsmcastMac_tlbMac").__len__()

        # capacity check need_modify
        if(index_len != 8):
            print(f"             [Multicast - Multicast MAC] FW capacity: {index_len} != 8 Test Fail",file = open(file_name, '+a')) 
            if_FW_error = True
        
        for index in range(index_len):
            if(driver.find_elements(By.CLASS_NAME, "td-table-content.rpsmcastMac_tlbMac")[index].get_attribute("textContent") != f"01:80:5e:00:00:0{index+1}"):
                if_mac_error_fw = True
            if(driver.find_elements(By.CLASS_NAME, "td-table-content.rpsmcastMac_tlbVlan")[index].get_attribute("textContent") != "4094"):
                if_nini_valn_error_fw = True
        if(if_mac_error_fw == True):
            print(f"             [Multicast - Static Multicast - Multicast MAC] FW MAC Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        else:
            print(f"             [Multicast - Static Multicast - Multicast MAC] FW MAC Test Pass",file = open(file_name, '+a'))
        if(if_nini_valn_error_fw == True):
            print(f"             [Multicast - Static Multicast - Multicast MAC] FW NINI-VLAN:4094 Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        else:
            print(f"             [Multicast - Static Multicast - Multicast MAC] FW NINI-VLAN:4094 Test Pass",file = open(file_name, '+a'))
        
        # --------------------- FW web end ------------------------

