def Multicast_Multicast_IP(driver,url,list_element,username,password,file_name):
    print(f"EMS - Multicast - Multicast IP Test\n",file = open(file_name, '+a'))    
    # for list_element in list1:    
    #     print(f"             ({list_element})",file = open(file_name, '+a'))        
    #     slot = list_element.split(",")[1]
    #     port = list_element.split(",")[2]
    #     cardtype = list_element.split(",")[3]
    #     # print(f"Now in case:{list_element[:1]},  Slot-Port:{slot}-{port}, {cardtype}")
    #     print(f"             Now in case:{list_element[:1]},  Slot-Port:{slot}-{port}, {cardtype}",file = open(file_name, '+a'))

    #     match list_element[:1]:            
    #         case "1":
    #             if("1440" in cardtype):              
    #                 output_id = '0000'      # GLC1440
    #             else:
    #                 output_id = '0000'      # GLC1540
                
    #             Multicast_Multicast_IP_1(driver,url,slot,port,output_id,username,password,file_name)                  

    #         case "2":
    #             if("3416B" in cardtype):              
    #                 output_id = '0000'      # OLC3416B        
    #             elif ("3708" in cardtype):
    #                 output_id = '0000'      # OLC3708
    #             else:
    #                 output_id = '0000'      # OLC3816
    #             print(f"             {NO_ACTION}",file = open(file_name, '+a'))                 
    #         case "3":
    #             output_id = '0000'          # OLC3416     
    #             print(f"             {NO_ACTION}",file = open(file_name, '+a'))             
    #         case _:                
    #             print(f"             No Action (not in any case)",file = open(file_name, '+a'))                           
    #     print(f"",file = open(file_name, '+a'))
    slot = list_element.split(",")[1]
    port = list_element.split(",")[2]
    cardtype = list_element.split(",")[3]
    match list_element[:1]:            
        case "1":
            if("1440" in cardtype):              
                output_id = '0000'      # GLC1440
            else:
                output_id = '0000'      # GLC1540
            
            Multicast_Multicast_IP_1(driver,url,slot,port,output_id,username,password,file_name)                  

        case "2":
            if("3416B" in cardtype):              
                output_id = '0000'      # OLC3416B        
            elif ("3708" in cardtype):
                output_id = '0000'      # OLC3708
            else:
                output_id = '0000'      # OLC3816
            print(f"             {NO_ACTION}",file = open(file_name, '+a'))                 
        case "3":
            output_id = '0000'          # OLC3416     
            print(f"             {NO_ACTION}",file = open(file_name, '+a'))     
        case "4":                
            print(f"             MSC case (undone*)",file = open(file_name, '+a'))
            print(f"             {NO_ACTION}",file = open(file_name, '+a'))        
        case _:                
            print(f"             No Action (not in any case)",file = open(file_name, '+a'))  
    print("======================================================================================",file = open(file_name, '+a'))

    
def Multicast_Multicast_IP_1(driver,url,slot,port,output_id,username,password,file_name):
    print(f"EMS - Multicast - Multicast IP Test\n",file = open(file_name, '+a')) 
    if_EMS_error = False
    if_FW_error = False

    # --------------------- EMS web start ---------------------
    # EMS - Multicast - Multicast IP
    
    # EMS website > login
    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,"Pqa1234!!")
    time.sleep(5)    
    EMS_Provision_Config_path(driver,url)
    time.sleep(2)    
    driver.find_element(By.LINK_TEXT, "Multicast").click()          
    time.sleep(1)
    driver.find_element(By.LINK_TEXT, "Multicast IP").click()
    time.sleep(3)

    # check if clear, if not, delete   need_modify

    # select Slot Port
    try:
        e_mul.Multicast_IP_Select_Slot(driver,slot)
    except:
        if_EMS_error = True
        print(f"             [Multicast - Multicast IP] EMS Slot select fail",file = open(file_name, '+a')) 
    try:
        e_mul.Multicast_IP_Select_Port(driver,port)
    except:
        if_EMS_error = True
        print(f"             [Multicast - Multicast IP] EMS Port select fail",file = open(file_name, '+a')) 

    if(if_EMS_error == False):

        # e_mul.Multicast_IP_Load(driver)

        # Multicast IP Apply
        index = 0
        if_full = False
        # while(if_full == False):
        while(if_full == False and index < 10):
            index = index+1
            e_mul.Multicast_IP_Address(driver,f"224.0.0.{index}")
            e_mul.Multicast_IP_NNI_VLAN(driver,"4094")
            e_mul.Multicast_IP_Role(driver,"Forbid")
            e_mul.Multicast_IP_Add(driver)
            msg = alert_accept_text(driver)
            if(if_msg_not_success(msg)):
                print(f"             [Multicast - Multicast IP] EMS msg:{msg} (counter:{index})",file = open(file_name, '+a'))
            # try:
            #     driver.find_element(By.NAME, "rperror_btnBack").click()
            #     print(f"             [Multicast - Static Multicast - Multicast MAC] Max Capacity(8) = {index-1}",file = open(file_name, '+a'))
            #     if_full = True
            # except:
            #     pass

        # capacity check need_modify
        capacity_num_temp = driver.find_elements(By.CLASS_NAME, "zy_tr.multicast_mcastip_table_row").__len__()
        print(f"             [Multicast - Multicast IP] EMS capacity:{capacity_num_temp} ?",file = open(file_name, '+a')) 

        if_ip_error = False
        if_nini_valn_error = False
        if_role_error = False

        # Multicast IP Check                     
        index_len = driver.find_elements(By.CLASS_NAME, "zy_tr.multicast_mcastip_table_row").__len__()
        for index in range(index_len):
            e = driver.find_elements(By.CLASS_NAME, "zy_td.multicast_mcastip_ip")[index].get_attribute("textContent")
            # if(e != f"01:80:5e:00:00:0{index+1}"):
            if(e != f"224.0.0.{index+1}"):
                if_ip_error = True
                # print(f"             [Multicast - Multicast IP] EMS index {index} IP Test Fail ({e}!=01:80:5e:00:00:0{index+1})",file = open(file_name, '+a'))
                print(f"             [Multicast - Multicast IP] EMS index {index} IP Test Fail ({e}!=224.0.0.{index+1})",file = open(file_name, '+a'))
            e = driver.find_elements(By.CLASS_NAME, "zy_td.multicast_mcastip_nnivlan")[index].get_attribute("textContent")
            if(e != "4094"):
                if_nini_valn_error = True
                print(f"             [Multicast - Multicast IP] EMS index {index} NINI-VLAN Test Fail ({e}!=4094)",file = open(file_name, '+a'))
            e = driver.find_elements(By.CLASS_NAME, "zy_td.multicast_mcastip_role")[index].get_attribute("textContent")
            if(e != "Forbid"):
                if_role_error = True    
                print(f"             [Multicast - Multicast IP] EMS index {index} IP Test Fail ({e}!=Forbid)",file = open(file_name, '+a'))
        if(if_ip_error == True):
            # print(f"             [Multicast - Multicast IP] EMS IP Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [Multicast - Multicast IP] EMS IP Test Pass",file = open(file_name, '+a'))
        if(if_nini_valn_error == True):
            # print(f"             [Multicast - Multicast IP] EMS NINI-VLAN:4094 Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [Multicast - Multicast IP] EMS NINI-VLAN:4094 Test Pass",file = open(file_name, '+a'))
        if(if_role_error == True):
            # print(f"             [Multicast - Multicast IP] EMS Role:Forbid Test Fail",file = open(file_name, '+a'))
            if_EMS_error = True
        else:
            print(f"             [Multicast - Multicast IP] EMS Role:Forbid Test Pass",file = open(file_name, '+a'))

        # --------------------- EMS web end -----------------------
        # --------------------- FW web start ----------------------
        # Multicast > Static Multicast > Multicast IP
        driver.get(url) 
        time.sleep(3)
        mod.Login(driver,username,password)      
        # 路徑導向 Multicast > Static Multicast > Multicast IP
        mod.Switch_Default(driver)
        mod.Page_Switch(driver,"Multicast")
        mod.SubPage_Switch(driver,"Static Multicast")
        mod.Switch_Frame(driver)
        mod.SubPage_Switch(driver,"Multicast IP")  
        time.sleep(1)
        mul.Slot_Select(driver,slot)
        time.sleep(1)
        mul.Port_Select(driver,port)
        time.sleep(1)
        mul.Load(driver)
        time.sleep(1)

        if_IP_error = False
        if_nini_valn_error = False
        if_role_error = False

        # Multicast IP Check
        index_len = driver.find_elements(By.CLASS_NAME, "td-table-content.rpsmcastIp_tlbIp").__len__()
        
        # capacity check need_modify
        print(f"             [Multicast - Multicast IP] FW capacity:{index_len} ?",file = open(file_name, '+a')) 
        
        for index in range(index_len):
            if(driver.find_elements(By.CLASS_NAME, "td-table-content.rpsmcastIp_tlbIp")[index].get_attribute("textContent") != f"224.0.0.{index}"):
                if_IP_error = True
            if(driver.find_elements(By.CLASS_NAME, "td-table-content.rpsmcastIp_tlbVlan")[index].get_attribute("textContent") != "4094"):
                if_nini_valn_error = True
            if(driver.find_elements(By.CLASS_NAME, "td-table-content.rpsmcastIp_tlbRole")[index].get_attribute("textContent") != "Forbid"):
                if_role_error = True
        if(if_IP_error == True):
            print(f"             [Multicast - Static Multicast - Multicast IP] FW IP Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        else:
            print(f"             [Multicast - Static Multicast - Multicast IP] FW IP Test Pass",file = open(file_name, '+a'))
        if(if_nini_valn_error == True):
            print(f"             [Multicast - Static Multicast - Multicast IP] FW NINI-VLAN:4094 Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        else:
            print(f"             [Multicast - Static Multicast - Multicast IP] FW NINI-VLAN:4094 Test Pass",file = open(file_name, '+a'))
        if(if_role_error == True):
            print(f"             [Multicast - Static Multicast - Multicast IP] FW Role:Forbid Test Fail",file = open(file_name, '+a'))
            if_FW_error = True
        else:
            print(f"             [Multicast - Static Multicast - Multicast IP] FW Role:Forbid Test Pass",file = open(file_name, '+a'))
        # --------------------- FW web end ------------------------


    # EMS Result
    if(if_EMS_error == True):
        print(f"             [Multicast - Multicast IP] EMS web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Multicast - Multicast IP] EMS web check pass",file = open(file_name, '+a')) 

    # FW Result
    if(if_FW_error == True):
        print(f"             [Multicast - Multicast IP] FW web check fail",file = open(file_name, '+a'))
    else:
        print(f"             [Multicast - Multicast IP] FW web check pass",file = open(file_name, '+a')) 

    # Final Result    
    if((if_EMS_error == False) and (if_FW_error == False)):
        print(f"  [EMS1-{output_id}][Multicast - Multicast IP] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"  [EMS1-{output_id}][Multicast - Multicast IP] Result Fail",file = open(file_name, '+a'))


