    #     if_EMS_error = True
    

    for test_port in range(1,41):
        e_swi.Switch_Storm_Control_Slot_Select(driver,slot)
        e_swi.Switch_Storm_Control_Port_Select(driver,str(test_port))
        e_swi.Switch_Storm_Control_Broadcast(driver,storm_control_num)
        e_swi.Switch_Storm_Control_DLF(driver,storm_control_num)
        e_swi.Switch_Storm_Control_Multicast(driver,storm_control_num)
        e_swi.Switch_Setup_Storm_Control_Save(driver)
        msg = alert_accept_text(driver)
        if(if_msg_not_success(msg)):
            print(f"             [Switch - Storm Control] EMS Port{test_port} save msg:{msg}",file = open(file_name, '+a'))

        # check broadcast
        temp = driver.find_element(By.ID ,"sw_stormctrl_broadcast_text").get_attribute("value")
        if(temp != str(storm_control_num)):
            print(f"             [Switch - Storm Control] EMS Port{test_port} Broadcast Test Fail ({temp}!={storm_control_num})",file = open(file_name, '+a'))
            if_EMS_error = True
        # check DLF
        temp = driver.find_element(By.ID ,"sw_stormctrl_def_text").get_attribute("value")
        if(temp != str(storm_control_num)):
            print(f"             [Switch - Storm Control] EMS Port{test_port} DLF Test Fail ({temp}!={storm_control_num})",file = open(file_name, '+a'))
            if_EMS_error = True
        # check Multicast
        temp = driver.find_element(By.ID ,"sw_stormctrl_multi_text").get_attribute("value")
        if(temp != str(storm_control_num)):
            print(f"             [Switch - Storm Control] EMS Port{test_port} Multicast Test Fail ({temp}!={storm_control_num})",file = open(file_name, '+a'))
