    mod.Page_Switch(driver,"Switch")
    mod.SubPage_Switch(driver,"Switch Setup")
    mod.Switch_Frame(driver)
    mod.Tab_Switch(driver,"Storm Control")

    # slot select
    time.sleep(1)
    swi.Switch_Setup_Storm_Control_Slot_Select(driver,slot)
    time.sleep(1)

    # check
    if(driver.find_element(By.NAME, f"rpsw_setup_storm_control_ipt_broadcast{int(port)-1}").get_attribute("value") != str(storm_control_num)):
        print(f"             [Switch - Switch Setup - Storm Control] FW Port{port} Broadcast Test Fail",file = open(file_name, '+a'))
        if_FW_error = True
    if(driver.find_element(By.NAME, f"rpsw_setup_storm_control_ipt_dlf{int(port)-1}").get_attribute("value") != str(storm_control_num)):
        print(f"             [Switch - Switch Setup - Storm Control] FW Port{port} DLF Test Fail",file = open(file_name, '+a'))
        if_FW_error = True
    if(driver.find_element(By.NAME, f"rpsw_setup_storm_control_ipt_multicast{int(port)-1}").get_attribute("value") != str(storm_control_num)):
        print(f"             [Switch - Switch Setup - Storm Control] FW Port{port} Multicast Test Fail",file = open(file_name, '+a'))
        if_FW_error = True    

