    if(SUCCESS_TEXT in msg):
        print(f"             [Switch - Storm Control] EMS DLF invalid Test Fail",file = open(file_name, '+a'))
        if_EMS_error = True
    e_swi.Switch_Storm_Control_DLF(driver,storm_control_num)
    e_swi.Switch_Setup_Storm_Control_Save(driver)    
    alert_accept(driver)

    # Multicast: max+1 test     (%slot %port)
    e_swi.Switch_Storm_Control_Slot_Select(driver,slot)
    e_swi.Switch_Storm_Control_Port_Select(driver,port)
    e_swi.Switch_Storm_Control_Multicast(driver,storm_control_num+1)
