def Delete_Profile_Test(driver,index_name,profile_type,file_name,timeout1=10):

    # example: Delete_Profile(driver,index_name,'ONT Service Profile',file_name)
    # return True if error

    try:
        e_pro.Profile_Path(driver,profile_type)
    except:
        pass

    if_temp_error = False

    index = e_pro.Profile_Name_Search(driver,index_name)
    if(index != -1):
        e_pro.Profile_Table_List_Checkbox(driver,index)
        e_pro.Delete_Profile(driver)
        # check  alert  
        msg = alert_accept_text(driver,timeout1)
        if(if_msg_not_success(msg)):
            print(f"             [Profile - {profile_type}] msg:{msg} {index_name} Alert Delete Test Fail",file = open(file_name, '+a'))
            if_temp_error = True
        else:
            print(f"             [Profile - {profile_type}] msg:{msg} {index_name} Alert Delete Test Pass",file = open(file_name, '+a'))
        # reload page
        driver.find_element(By.LINK_TEXT,"Provision").click()
        time.sleep(1)
        driver.find_element(By.LINK_TEXT,"Profile").click()
        time.sleep(1)
        e_pro.Profile_Select(driver, profile_type)
        time.sleep(1)
        # check profile name should not show in table            
        if(e_pro.Profile_Name_Search_only(driver,index_name) == True):
            print(f"             [Profile - {profile_type}] found {index_name} after delete Delete Test Fail",file = open(file_name, '+a'))
            if_temp_error = True
        else:
            print(f"             [Profile - {profile_type}] not found {index_name} after delete Delete Test Pass",file = open(file_name, '+a'))
    else:         
        if_temp_error = True
        print(f"             [Profile - {profile_type}] delete target:{index_name} not found before delete Delete Test Fail",file = open(file_name, '+a'))     

    return if_temp_error

