def Create_ONT_QoS_Bandwidth_Profile(driver,username,ems_password,file_name,prof_name='!!!Auto_DoNotDelete_qos_profile'):
    output_case_name = "Profile - ONT QoS Bandwidth Profile"
    print(f"             Create EMS - Profile - ONT QoS Bandwidth Profile",file = open(file_name, '+a')) 
    if_error = False
    if_error_info = False

    # --------------------- EMS web start ---------------------
    # EMS - Profile - ONT Qos Bandwidth Profile

    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)

    e_pro.Profile_Path(driver,"ONT QoS Bandwidth Profile")

    # Test Start ...  
    # prof_name = '!!!Auto_create_xxx'
    # prof_name =  '!!!Auto_DoNotDelete_qos_profile'
    Delete_Profile_1(driver,prof_name,'ONT QoS Bandwidth Profile',file_name,30)
    if(If_Profile_Table_Full(driver,'EMS1-0000','ONT QoS Bandwidth Profile',file_name,30) == True):
        return
    
    if_error = False
    e_pro.QoS_Bandwidth_Profile_New(driver)
    e_pro.QoS_Bandwidth_Profile_New_Name(driver,prof_name)
    e_pro.QoS_Bandwidth_Profile_New_sir(driver,"500000")
    e_pro.QoS_Bandwidth_Profile_New_air(driver,"500000")
    e_pro.QoS_Bandwidth_Profile_New_pir(driver,"10000000")
    # GPON Fallback Rate
    e_pro.QoS_Bandwidth_Profile_New_GPON_Fallback_Rate_SIR(driver,'600000')
    e_pro.QoS_Bandwidth_Profile_New_GPON_Fallback_Rate_AIR(driver,'600000')
    e_pro.QoS_Bandwidth_Profile_New_GPON_Fallback_Rate_PIR(driver,'1200000')
    e_pro.QoS_Bandwidth_Profile_New_Apply(driver)
    msg = alert_accept_text(driver,30)
    if(if_msg_not_success(msg)):
        print(f"             [Profile - ONT QoS Bandwidth Profile] msg:{msg} Valid Input Alert Test Fail",file = open(file_name, '+a'))
        if_error = True
    else:
        print(f"             [Profile - ONT QoS Bandwidth Profile] msg:{msg} Valid Input Alert Test Pass",file = open(file_name, '+a'))
    if(if_error == False):
        print(f"           [][Profile - ONT QoS Bandwidth Profile] Result Pass",file = open(file_name, '+a'))
    else:
        print(f"           [][Profile - ONT QoS Bandwidth Profile] Result Fail",file = open(file_name, '+a'))
    
    print("",file = open(file_name, '+a'))

