def Create_ONT_Multicast_Profile(driver,username,ems_password,file_name,multicast_prof_name="!!!AutoTest_DoNotDelete_mulxxxx"):
    print(f"             Create EMS - Profile - ONT Multicast Profile",file = open(file_name, '+a')) 

    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)
    
    # Test Start

    print(f"             [Profile - Multicast Profile] create igmp profile...",file = open(file_name, '+a'))        
    Create_IGMP_Group_Privilege_Profile(driver,username,ems_password,file_name)
    IGMP_prof_name = "!!!AutoTest_DoNotDelete_xxxxxxx" # "1234567890123456789012345678001"
    # multicast_prof_name = "!!!AutoTest_DoNotDelete_mulxxxx" # _____xpon_multicast_profile_SFU

    e_pro.Profile_Path(driver,"ONT Multicast Profile")
    
    Delete_Profile_1(driver,multicast_prof_name,'ONT Multicast Profile',file_name)
    if(If_Profile_Table_Full(driver,'EMS1-5572','ONT Multicast Profile',file_name) == True):
        return
    
    if_error = False
    e_pro.Multicast_Profile_New(driver)
    e_pro.Multicast_Profile_New_Name(driver,multicast_prof_name)
    e_pro.Multicast_Profile_New_UNI_VID(driver,"4094")
    e_pro.Multicast_Profile_New_Tx_Tag_VID(driver,"")
    e_pro.Multicast_Profile_New_Max_Group(driver,"512")
    e_pro.Multicast_Profile_New_Max_Message(driver,"64")
    e_pro.Multicast_Profile_New_IGMP_Version(driver,"IGMPv2")
    e_pro.Multicast_Profile_New_Tx_Tag_Mode(driver,"untag")
    e_pro.Multicast_Profile_New_Tx_Tag_Pbit(driver,"0")
    try:
        e_pro.Multicast_Profile_New_Group_Privilege_Profile(driver,IGMP_prof_name)
    except:
        print(f"             [Profile - ONT Multicast Profile] no found Group Privilege Profile '{IGMP_prof_name}' ",file = open(file_name, '+a'))        
    e_pro.Multicast_Profile_New_Apply(driver)
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"           [][Profile - ONT Multicast Profile] msg:{msg} {multicast_prof_name} Create Fail",file = open(file_name, '+a'))        
        if_error = True
    else:
        print(f"           [][Profile - ONT Multicast Profile] msg:{msg} {multicast_prof_name} Create Pass",file = open(file_name, '+a'))        

    
    # if(if_error == False):
    #     print(f"  [EMS1-0000][Profile - ONT Multicast Profile - New] Result Pass\n",file = open(file_name, '+a'))
    # else:
    #     print(f"  [EMS1-0000][Profile - ONT Multicast Profile - New] Result Fail\n",file = open(file_name, '+a'))
    
    print(f"",file = open(file_name, '+a'))        

    

