def Create_ONT_VoIP_Dial_Plan_Profile(driver,username,ems_password,file_name):
    print(f"             Create EMS - Profile - ONT VoIP Dial Plan Profile",file = open(file_name, '+a')) 
    e_pro.Profile_Path(driver,"ONT VoIP Dial Plan Profile")

    # Start

    if(If_Profile_Table_Full(driver,'EMS1-    ','ONT VoIP Dial Plan Profile',file_name) == True):
        return

    dial_plan_profile_name = "__dial_plan_SFU"
    dial_plan_profile_print_name = ["SFU","HGU"]
   
    e_pro.Dial_Plan_Profile_New(driver)
    e_pro.Dial_Plan_Profile_New_Name(driver,dial_plan_profile_name)
    e_pro.Dial_Plan_Profile_New_MS(driver,"256")
    e_pro.Dial_Plan_Profile_New_CDT(driver,"8000")
    e_pro.Dial_Plan_Profile_New_PDT(driver,"32000")
    e_pro.Dial_Plan_Profile_New_format(driver,'H248') #* 4
    time.sleep(1)
    e_pro.Dial_Plan_Profile_New_CT(driver,"0123456789012345678901234567")### content-table token Test
    time.sleep(1)
    e_pro.Dial_Plan_Profile_New_Apply(driver)
    # check alert
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"           [][Profile - ONT VoIP Dial Plan Profile] msg:{msg} Create Fail",file = open(file_name, '+a'))
        if_error = True
    else:
        print(f"           [][Profile - ONT VoIP Dial Plan Profile] msg:{msg} Create Pass",file = open(file_name, '+a'))

    print("",file = open(file_name, '+a'))

def ONT_ACL_Profile(driver,username,ems_password,file_name):
    print(f"EMS - Profile - ONT ACL Profile Test\n",file = open(file_name, '+a')) 

    # --------------------- EMS web start ---------------------
    # EMS - Profile - ONT ACL Profile

    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)

    e_pro.Profile_Path(driver,"ONT ACL Profile")


    # Test Start

    acl_pname = ['____xpon_ACL_profile_SFU','____xpon_ACL_profile_HGU']

    # quantity_now =  driver.find_elements(By.CLASS_NAME,"tdCheckbox").__len__()
    # if(quantity_now > ACL_profile_capacity-2):
    #     driver.find_elements(By.XPATH,f"//*[@for='myCheckbox{quantity_now-1}_profile_table']").click()
    #     driver.find_elements(By.XPATH,f"//*[@for='myCheckbox{quantity_now-2}_profile_table']").click()               
    #     e_pro.ACL_Profile_Delete(driver)
    Delete_Profile_1(driver,'____xpon_ACL_profile_SFU','ONT ACL Profile',file_name)
    Delete_Profile_1(driver,'____xpon_ACL_profile_HGU','ONT ACL Profile',file_name)
    if(If_Profile_Table_Full(driver,'EMS1-4336','ONT ACL Profile',file_name) == True):
        return
    
    # NEW ---------------------------------------------------------------------
    # PROFILE INFO -------------------------------------------------------------
