    print(f"             [Profile - ONT ACL Profile] (Profile info)",file = open(file_name, '+a'))
    # for create_time in range(2):
    for create_time in range(1):
        time.sleep(3)
        e_pro.ACL_Profile_New(driver)
        e_pro.ACL_Profile_New_Name(driver,acl_pname[create_time])
        time.sleep(2)
        e_pro.ACL_Profile_New_Enable(driver,True)
        e_pro.ACL_Profile_New_Policy(driver,"Trust")
