                if(driver.find_element(By.ID,"ont_alarm_uprxpower_text").get_attribute("value") != "0"):
                    print(f"             [Profile - ONT Alarm Profile] SFU Up rxpower thresh:0.0 Test Fail",file = open(file_name, '+a'))
                    if_error = True    
                else:
                    print(f"             [Profile - ONT Alarm Profile] SFU Up rxpower thresh:0.0 Test Pass",file = open(file_name, '+a'))
                if(driver.find_element(By.ID,"ont_alarm_lowtemp_text").get_attribute("value") != "100"):
                    print(f"             [Profile - ONT Alarm Profile] SFU Low temp:100 Test Fail",file = open(file_name, '+a'))
                    if_error = True   
