def Create_ONT_Alarm_Profile(driver,username,ems_password,file_name,alarm_prfname = '!!!Auto_create_alarm_profile_xx'):
    print(f"             Create EMS - Profile - ONT Alarm Profile",file = open(file_name, '+a')) 

    # --------------------- EMS web start ---------------------
    # EMS - Profile - ONT Service Profile

    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)

    e_pro.Profile_Path(driver,"ONT Alarm Profile")

    # Test Start
    # alarm_prfname = '!!!Auto_create_alarm_profile_xx'
    Delete_Profile_1(driver,alarm_prfname,'ONT Alarm Profile',file_name)
    if(If_Profile_Table_Full(driver,'EMS1-0000','ONT Alarm Profile',file_name) == True):
        return

    if_error_new = False
    if_error = False
    e_pro.Ont_Alarm_Profile_New(driver)
    e_pro.Ont_Alarm_Profile_New_Name(driver,alarm_prfname)
    e_pro.Ont_Alarm_New_Low_Current_Threshold(driver,"79") #*not sure what value should input
    e_pro.Ont_Alarm_New_Up_Current_Threshold(driver,"79")
    e_pro.Ont_Alarm_New_Low_rxpower_thresh(driver,"0")
    e_pro.Ont_Alarm_New_Up_rxpower_thresh(driver,"0")
    e_pro.Ont_Alarm_New_Low_temp(driver,"100")
    e_pro.Ont_Alarm_New_Up_temp(driver,"100")
    e_pro.Ont_Alarm_New_Low_txpower_thresh(driver,"6.5")
    e_pro.Ont_Alarm_New_Up_txpower_thresh(driver,"6.5")
    e_pro.Ont_Alarm_New_Low_volt_thresh(driver,"3.59")    
    e_pro.Ont_Alarm_New_Up_volt_thresh(driver,"3.59")
    e_pro.Ont_Alarm_Profile_New_Apply(driver)

    # check alert 
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"           [][Profile - ONT Alarm Profile] msg:{msg} {alarm_prfname} Create Fail",file = open(file_name, '+a'))        
        if_error_new = True
    else:
        print(f"           [][Profile - ONT Alarm Profile] msg:{msg} {alarm_prfname} Create Pass",file = open(file_name, '+a'))        
    
    print("",file = open(file_name, '+a'))
    
def ONT_ONT_Profile(driver,username,ems_password,file_name) :

    print(f"EMS - Profile - ONT ONT Profile Test\n",file = open(file_name, '+a')) 
    # EMS - Profile - ONT ONT Profile    

    # --------------------- EMS web start ---------------------
    if_error = False
    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)

    # need to create name in [VoIP Common Profile], [Sip Profile], [Dial Plan Profile] pages first,
    # Ont > VoIP page need them, create them before create ONT Profile page
    # ...
    # Create Voip Sip Profile
    Create_ONT_VoIP_Sip_Profile(driver,username,ems_password,file_name)
    # Create Voip Common Profile
    Create_ONT_VoIP_Common_Profile(driver,username,ems_password,file_name)
    # Create Voip Dial Plan Profile
    Create_ONT_VoIP_Dial_Plan_Profile(driver,username,ems_password,file_name)
    acl_prof = "!!!Auto_ACL_profile_xxxx"
    Create_ONT_ACL_Profile(driver,username,ems_password,file_name)  

    # Test Start

    e_pro.Profile_Path(driver,"ONT ONT Profile")
    
    Delete_Profile_1(driver,'___________xpon_ont_profile_SFU','ONT ONT Profile',file_name)
    Delete_Profile_1(driver,'___________xpon_ont_profile_HGU','ONT ONT Profile',file_name)
    if(If_Profile_Table_Full(driver,'EMS1-5575','ONT ONT Profile',file_name) == True):
        return

    ont_profile_name = ["___________xpon_ont_profile_SFU","___________xpon_ont_profile_HGU"]
    ont_profile_print_name = ["SFU","HGU"]
    # NEW ---------------------------------------------------------------------
    # PROFILE INFO -------------------------------------------------------------
    if_error_new = False
    if_error = False
    print(f"             [Profile - ONT ONT Profile] (New)",file = open(file_name, '+a'))
    print(f"             [Profile - ONT ONT Profile] (Profile info)",file = open(file_name, '+a'))
    # for create_time in range(2):
    for create_time in range(1):
        e_pro.Ont_Profile_New(driver)
        e_pro.Ont_Profile_New_Name(driver,ont_profile_name[create_time])
        e_pro.Ont_Profile_New_Service_Control(driver,True)
        e_pro.Ont_Profile_New_Service_lcmp_enable(driver,"L&W")
        e_pro.Ont_Profile_New_Service_ftp_enable(driver,"L&W")
        e_pro.Ont_Profile_New_Service_Http_enable(driver,"L&W")
        e_pro.Ont_Profile_New_Service_Https_enable(driver,"L&W")
        e_pro.Ont_Profile_New_Service_Snmp_enable(driver,"L&W")
        e_pro.Ont_Profile_New_Service_Telnet_enable(driver,"L&W")
        e_pro.Ont_Profile_New_Service_SSH_enable(driver,"L&W")
        e_pro.Ont_Profile_New_Service_Firewall_control(driver,True)
        scroll_ele = driver.find_element('id','profile_content_div')
        Scroll(driver,scroll_ele)
        e_pro.Ont_Profile_New_Service_Firewall_enable(driver,"ALL")
        e_pro.Ont_Profile_New_Service_Firewall_level(driver,"high")
        e_pro.Ont_Profile_New_Service_Dmz_control(driver,True)
