def Create_ONT_UNI_Profile(driver,username,ems_password,file_name,uni_profile_name="!!!Auto_DoNotDelete_uni_profile"):
    print(f"             Create EMS - Profile - ONT UNI Profile",file = open(file_name, '+a')) 
    if_error = False

    # --------------------- EMS web start ---------------------
    # EMS - Profile - ONT UNI Profile

    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)

    e_pro.Profile_Path(driver,"ONT UNI Profile")

    # uni_profile_name = "___________xpon_uni_profile_SFU"
    # uni_profile_name = "!!!Auto_DoNotDelete_uni_profile"
    Delete_Profile_1(driver,uni_profile_name,'ONT UNI Profile',file_name)
    if(If_Profile_Table_Full(driver,'EMS1-0000','ONT UNI Profile',file_name) == True):
        return

    if_error_new = False
    if_error = False
        
    e_pro.Uni_Profile_New(driver)
    # pro.Uni_Profile_New_Name(driver,"___________xpon_uni_profile_SFU")
    e_pro.Uni_Profile_New_Name(driver, uni_profile_name)        

    # LAN
    e_pro.Uni_Profile_New_Lan_Vlan_Active(driver,1,True)
