def X_Create_ONT_Template(driver,username,ems_password,file_name): # X
    # return
    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)

    e_pro.Profile_Path(driver,"ONT Template")

    # Test Start
    create_name = ["SFU","HGU"]
    template_profname = ['!!!Auto_DoNotDelete_templat_SFU','!!!Auto_DoNotDelete_templat_HGU']
    uni_p = "!!!Auto_DoNotDelete_uni_profile"
    sec_p = "!!!Auto_DoNotDelete_security_xx" 
    ala_p = "!!!Auto_create_alarm_profile_xx" 
    ont_p = "!!!Auto_DoNotDelete_ont_profile" 
    ser_p = "!!!Auto_____service_profile_SFU" 
    qos_p = "!!!Auto_DoNotDelete_qos_profile" 
    mul_p = "!!!AutoTest_DoNotDelete_mulxxxx" 
    Create_ONT_UNI_Profile(driver,username,ems_password,file_name)
    Create_ONT_Security_Profile(driver,username,ems_password,file_name)
    Create_ONT_Alarm_Profile(driver,username,ems_password,file_name)
    Create_ONT_ONT_Profile(driver,username,ems_password,file_name)
    Create_ONT_Service_Profile(driver,username,ems_password,file_name)
    Create_ONT_QoS_Bandwidth_Profile(driver,username,ems_password,file_name)
    Create_ONT_Multicast_Profile(driver,username,ems_password,file_name)

    Delete_Profile_1(driver,template_profname[0],'ONT Template',file_name)
    if(If_Profile_Table_Full(driver,'0','ONT Template',file_name) == True):
        return    

    if_error_new = False
    if_error = False
    if_break = False
    # for create_time in range(2):
    for create_time in range(1):  # SFU HGU 設的值一樣?
        e_pro.Template_New(driver)
        e_pro.Template_New_Name(driver,template_profname[0])
        try:
            e_pro.Template_New_Main_UNI_Profile(driver,uni_p)
        except:
            print(f"             [Profile - ONT Template] UNI Profile {uni_p} Select Fail",file = open(file_name, '+a'))
            if_error_new = True
        try:
            e_pro.Template_New_Main_Security_Profile(driver,sec_p)
        except:
            print(f"             [Profile - ONT Template] Security Profile {sec_p} Select Fail",file = open(file_name, '+a'))
            if_error_new = True
        try:
            e_pro.Template_New_Main_Alarm_Profile(driver,ala_p)
        except:
            print(f"             [Profile - ONT Template] Alarm Profile {ala_p} Select Fail",file = open(file_name, '+a'))
            if_error_new = True
                
        try:                                         
            e_pro.Template_New_Main_Ont_Profile(driver,ont_p)
        except:
            print(f"             [Profile - ONT Template] Ont Profile {ont_p} Select Fail",file = open(file_name, '+a'))
            if_error_new = True

        time.sleep(3)

        e_pro.Template_New_Service_Profile_Active_Select(driver,8,True)
        try:                                            # _______xpon_service_profile_HGU
            e_pro.Template_New_Service_Profile_Select(driver,8,ser_p)
            print(f"")
        except:
            print(f"             [Profile - ONT Template] Service Profile {ser_p} Select Fail",file = open(file_name, '+a'))
            if_error_new = True
        e_pro.Template_New_Service_Shared_Priority_Select(driver,8,"7")
        try:
            e_pro.Template_New_Service_US_Bandwidth_Profile_Select(driver,8,qos_p)
            e_pro.Template_New_Service_DS_Bandwidth_Profile_Select(driver,8,qos_p)
        except:
            print(f"             [Profile - ONT Template] Service - QoS Bandwidth Profile {qos_p} Select Fail",file = open(file_name, '+a'))
            if_error_new = True
        time.sleep(10)

        e_pro.Template_New_Tcont_Service_List_Active_Select(driver,8,True)
        e_pro.Template_New_Tcont_Service_List_Select(driver,8,"8")
        try:
            e_pro.Template_New_Tcont_US_Bandwidth_Profile_Select(driver,8,qos_p)
            e_pro.Template_New_Tcont_DS_Bandwidth_Profile_Select(driver,8,qos_p)
        except:
            print(f"             [Profile - ONT Template] Tcont - QoS Bandwidth Profile {qos_p} Select Fail",file = open(file_name, '+a'))
            if_error_new = True
        e_pro.Template_New_Tcont_Type_Select(driver,8,"Best-Effort")
        
        e_pro.Template_New_Multicast_Profile_Active_Select(driver,4,True)
        try:
            e_pro.Template_New_Multicast_Profile_Select(driver,4,mul_p)
        except:
            print(f"             [Profile - ONT Template] Multicast Profile {mul_p} Select Fail",file = open(file_name, '+a'))
            if_error_new = True
        if(if_error_new == True):
            if_error = True
            print(f"             [Profile - ONT Template] Some profiles Select Fail",file = open(file_name, '+a'))
        else:        
            e_pro.Template_New_Apply(driver)

            # check alert
            msg = alert_accept_text(driver)
            if(if_msg_not_success(msg)):
                print(f"             [Profile - ONT Template] msg:{msg} Valid Input Apply Test Fail",file = open(file_name, '+a'))        
                if_error_new = True
            else:
                print(f"             [Profile - ONT Template] msg:{msg} Valid Input Apply Test Pass",file = open(file_name, '+a'))        

