def Create_Rate_Limit_Profile(driver,username,ems_password,file_name,prof_name = "!!!AutoTest_DoNotDelete_xxxxxxx"):

    print(f"             Create EMS - Profile - Rate Limit Profile",file = open(file_name, '+a')) 
    if_error = False

    # --------------------- EMS web start ---------------------
    # EMS - Profile - Rate Limit Profile

    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)
    e_pro.Profile_Path(driver,"Rate Limit Profile")

    # Test Start ...
    # 1234567890123456789012345678000
    Delete_Profile_1(driver,prof_name,'Rate Limit Profile',file_name)
    if(If_Profile_Table_Full(driver,'EMS1-0000','Rate Limit Profile',file_name) == True):
        return    
    
    e_pro.New_Profile(driver)
    e_pro.RateLimit_Profile_Name(driver,prof_name)    
    
    # INVALID TEST -------------------------------------------------------------------------
    if_error = False
    print(f"             [Profile - Rate Limit Profile] (New)",file = open(file_name, '+a'))
    # Invalid Input
    # Ingress CIR
    e_pro.RateLimit_Ingress_Checkbox(driver, True)
    
    scroll_ele = driver.find_element('id','profile_content_div')
    Scroll(driver,scroll_ele)
    
    
    # Valid Input       
    e_pro.RateLimit_Ingress(driver,True,"10000000","16000000","10000000","16000000")
    e_pro.RateLimit_Egress(driver,True,"10000000","128000")
    e_pro.RateLimit_Apply(driver)
    
    # check  alert  
    msg = alert_accept_text(driver)
    if(if_msg_not_success(msg)):
        print(f"             [Profile - Rate Limit Profile] msg:{msg} Valid Value Alert Test Fail",file = open(file_name, '+a'))
        if_error = True
    else:
        print(f"             [Profile - Rate Limit Profile] msg:{msg} Valid Value Alert Test Pass",file = open(file_name, '+a'))
    if(if_error == False):
        print(f"           [][Profile - Rate Limit Profile] Create Pass\n",file = open(file_name, '+a'))
    else:
        print(f"           [][Profile - Rate Limit Profile] Create Fail\n",file = open(file_name, '+a'))
    

def GE_Template(driver,username,ems_password,file_name):

    print(f"EMS - Profile - GE Template Test\n",file = open(file_name, '+a')) 
    if_error = False

    # --------------------- EMS web start ---------------------
    # EMS - Profile - GE Template 

    driver.get(EMS_IP)
    time.sleep(5)
    mod.Login_EMS(driver,username,ems_password)
    time.sleep(5)





    # Create IGMP Profile  - - - - - - - - - - - - - - -
    Create_IGMP_Group_Privilege_Profile(driver,username,ems_password,file_name)
    # Create Rate Limit Profile Profile  - - - - - - - - 
    Create_Rate_Limit_Profile(driver,username,ems_password,file_name)
    # Create Shaping  Profile  - - - - - - - - - - - - -
    Create_Shaping_Profile(driver,username,ems_password,file_name)
    # Create Weight   Profile  - - - - - - - - - - - - -
    Create_Weight_Profile(driver,username,ems_password,file_name)

    igmp_prof_name = "!!!AutoTest_DoNotDelete_xxxxxxx" #"1234567890123456789012345678001"

    # GE Template Test - - - - - - - - - - - - - - - - -

    e_pro.Profile_Path(driver,"GE Template")

    # Test Start ...
    # profile_name = '1234567890123456789012345678000'
    profile_name = ['!!!GE_template_vlan_trunk_xxxxx','!!!GE_template_vlan_tls_xxxxx','!!!GE_template_vlan_translation']
    for prof_n in profile_name:
        Delete_Profile_1(driver,prof_n,'GE Template',file_name)
    if(If_Profile_Table_Full(driver,'EMS1-0000','GE Template',file_name) == True):
        return    
    
