def ont_google_sheet(sheet_name,ont_list):

    
    from selenium.webdriver.common.by import By
    import gspread
    from oauth2client.service_account import ServiceAccountCredentials
                
    def GetData(driver):

        dic1 = {}

        table_counter = 1
        if_exist = True
        while(if_exist == True):
            try:            
                testn = driver.find_element(By.XPATH, f"/html/body/table[{table_counter}]/tbody/tr[1]/td/a").text       # name    

                passn = driver.find_element(By.XPATH, f"/html/body/table[{table_counter+1}]/tbody/tr/td[1]/b" ).text    # pass n
                failn = driver.find_element(By.XPATH, f"/html/body/table[{table_counter+1}]/tbody/tr/td[2]/b" ).text    # fail n
                passandfail = f'{passn}/{failn}'
                
                dic1[testn] = passandfail
                table_counter = table_counter + 2            
            except:
                if_exist = False              

        return dic1

    def aph(num):
        num1 = num + 64    
        # print(f'{num} -> {chr(num1)}')
        return chr(num1)

    def strtonum(str): #(A~Z)
        # return int(ord(chr))-64

        # process each character
        num = 0
        for i in range (str.__len__()):
            x = str[str.__len__()-1-i]
            # print('-x',x)
            x = int(ord(x))-64
            # print('x-',x)
            num += x * (26 ** i)
            
            # print(num)

        return num

    def Print(text,file_name):
        print(text)
        print(text,file = open(file_name, '+a'))


    # MAIN =======================================================================================================================================================================

    # print("processing...")

    # Setup
